/* Generated by scripts/build-offline.mjs. No personal API responses are cached here. */
const VERSION=__VERSION__;
const ASSETS=__ASSETS__;
const CACHE='map-atelier-shell-'+VERSION;
const TIMEOUT=5000;
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 try{
  const page=await fetch('/',{cache:'reload',credentials:'same-origin',redirect:'error'});
  if(!page.ok||!(await page.clone().text()).includes('name="map-atelier-shell"'))throw Error('Authenticated application shell unavailable');
  await cache.put('/',page);
  for(const path of ASSETS){const r=await fetch(path,{cache:'reload',credentials:'same-origin',redirect:'error'});if(!r.ok)throw Error('Incomplete offline assets');await cache.put(path,r)}
  if(!self.registration.active)await self.skipWaiting();
 }catch(error){await caches.delete(CACHE);throw error}
})()));
